#!/usr/bin/env python3.11
import os
import re
from pathlib import Path
from collections import defaultdict

class CodeAnalyzer:
    def __init__(self, src_dir):
        self.src_dir = Path(src_dir)
        self.issues = defaultdict(list)
        
    def analyze_file(self, filepath):
        """Analisa um arquivo TypeScript para problemas comuns"""
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()
            lines = content.split('\n')
            
        rel_path = filepath.relative_to(self.src_dir)
        
        # 1. setTimeout sem clearTimeout correspondente
        settimeout_lines = []
        cleartimeout_lines = []
        for i, line in enumerate(lines, 1):
            if 'setTimeout' in line and '//' not in line[:line.find('setTimeout')] if 'setTimeout' in line else True:
                settimeout_lines.append(i)
            if 'clearTimeout' in line:
                cleartimeout_lines.append(i)
        
        if len(settimeout_lines) > len(cleartimeout_lines):
            self.issues['potential_timeout_leaks'].append({
                'file': str(rel_path),
                'settimeout_count': len(settimeout_lines),
                'cleartimeout_count': len(cleartimeout_lines),
                'lines': settimeout_lines
            })
        
        # 2. Loops sem await (possível bloqueio)
        for i, line in enumerate(lines, 1):
            if re.search(r'for\s*\(.*\)\s*{', line) or re.search(r'while\s*\(.*\)\s*{', line):
                # Verificar próximas 10 linhas por await
                has_await = any('await' in lines[j] for j in range(i, min(i+10, len(lines))))
                if not has_await and 'async' in content[:content.find(line) if line in content else 0]:
                    self.issues['blocking_loops'].append({
                        'file': str(rel_path),
                        'line': i,
                        'code': line.strip()
                    })
        
        # 3. Try-catch vazio ou que apenas loga
        for i, line in enumerate(lines, 1):
            if 'catch' in line and '{' in line:
                catch_block = []
                brace_count = 1
                j = i
                while j < len(lines) and brace_count > 0:
                    catch_block.append(lines[j].strip())
                    brace_count += lines[j].count('{') - lines[j].count('}')
                    j += 1
                
                catch_content = ' '.join(catch_block)
                # Catch que só loga ou está vazio
                if ('logger.warn' in catch_content or 'console.log' in catch_content) and 'throw' not in catch_content:
                    self.issues['silent_errors'].append({
                        'file': str(rel_path),
                        'line': i,
                        'code': line.strip()
                    })
        
        # 4. Arrays/Maps sem limite de tamanho
        for i, line in enumerate(lines, 1):
            if re.search(r'new\s+(Map|Set)\s*\(', line):
                # Verificar se há limpeza (clear, delete, size check) no arquivo
                has_cleanup = any(
                    '.clear()' in l or '.delete(' in l or '.size' in l 
                    for l in lines[i:min(i+50, len(lines))]
                )
                if not has_cleanup:
                    self.issues['unbounded_collections'].append({
                        'file': str(rel_path),
                        'line': i,
                        'code': line.strip()
                    })
        
        # 5. Promises sem catch
        for i, line in enumerate(lines, 1):
            if '.then(' in line and '.catch(' not in line and 'await' not in line:
                self.issues['unhandled_promises'].append({
                    'file': str(rel_path),
                    'line': i,
                    'code': line.strip()
                })
    
    def analyze_all(self):
        """Analisa todos os arquivos TypeScript"""
        for ts_file in self.src_dir.rglob('*.ts'):
            if '__tests__' not in str(ts_file):
                self.analyze_file(ts_file)
    
    def generate_report(self):
        """Gera relatório de problemas encontrados"""
        print("=" * 80)
        print("RELATÓRIO DE ANÁLISE DE CÓDIGO - BAILEYS-MOD")
        print("=" * 80)
        print()
        
        total_issues = sum(len(v) for v in self.issues.values())
        print(f"Total de problemas encontrados: {total_issues}\n")
        
        # 1. Timeout Leaks
        if self.issues['potential_timeout_leaks']:
            print("🔴 POTENCIAIS VAZAMENTOS DE TIMEOUT")
            print("-" * 80)
            for issue in self.issues['potential_timeout_leaks'][:10]:
                print(f"  Arquivo: {issue['file']}")
                print(f"  setTimeout: {issue['settimeout_count']} | clearTimeout: {issue['cleartimeout_count']}")
                print(f"  Linhas: {issue['lines'][:5]}")
                print()
        
        # 2. Blocking Loops
        if self.issues['blocking_loops']:
            print("🔴 LOOPS POTENCIALMENTE BLOQUEANTES")
            print("-" * 80)
            for issue in self.issues['blocking_loops'][:10]:
                print(f"  {issue['file']}:{issue['line']}")
                print(f"  {issue['code']}")
                print()
        
        # 3. Silent Errors
        if self.issues['silent_errors']:
            print("🟡 ERROS SILENCIOSOS (catch sem throw)")
            print("-" * 80)
            for issue in self.issues['silent_errors'][:10]:
                print(f"  {issue['file']}:{issue['line']}")
                print(f"  {issue['code']}")
                print()
        
        # 4. Unbounded Collections
        if self.issues['unbounded_collections']:
            print("🔴 COLEÇÕES SEM LIMITE (Map/Set)")
            print("-" * 80)
            for issue in self.issues['unbounded_collections'][:10]:
                print(f"  {issue['file']}:{issue['line']}")
                print(f"  {issue['code']}")
                print()
        
        # 5. Unhandled Promises
        if self.issues['unhandled_promises']:
            print("🟡 PROMISES SEM TRATAMENTO DE ERRO")
            print("-" * 80)
            for issue in self.issues['unhandled_promises'][:10]:
                print(f"  {issue['file']}:{issue['line']}")
                print(f"  {issue['code']}")
                print()
        
        return self.issues

if __name__ == '__main__':
    analyzer = CodeAnalyzer('/home/ubuntu/baileys-mod/src')
    analyzer.analyze_all()
    issues = analyzer.generate_report()
    
    # Salvar relatório em arquivo
    with open('/home/ubuntu/baileys-mod/PROBLEMAS_IDENTIFICADOS.txt', 'w') as f:
        f.write(f"Total de problemas: {sum(len(v) for v in issues.values())}\n\n")
        for category, items in issues.items():
            f.write(f"\n{category.upper()}: {len(items)} ocorrências\n")
            f.write("=" * 80 + "\n")
            for item in items:
                f.write(f"{item}\n")
